/**
 * LARP Games — app.js
 *
 * How it discovers games:
 *   It reads games/index.json (auto-generated by scan.py or scan.sh).
 *   Each entry: { "name": "My Game", "file": "mygame.html" }
 *   If that file doesn't exist it falls back to scanning for a games/ fetch
 *   but most browsers block directory listing, so the JSON is recommended.
 *
 * Favorites are stored in localStorage so they survive refreshes.
 */

(function () {
  // ── State ────────────────────────────────────────────────
  let allGames = [];   // { name, file, id }
  let favorites = new Set(JSON.parse(localStorage.getItem('larpFavs') || '[]'));
  let currentFilter = 'all';
  let searchQuery = '';

  // ── DOM refs ─────────────────────────────────────────────
  const grid        = document.getElementById('gamesGrid');
  const emptyState  = document.getElementById('emptyState');
  const emptyTitle  = document.getElementById('emptyTitle');
  const emptyMsg    = document.getElementById('emptyMsg');
  const searchInput = document.getElementById('searchInput');
  const clearBtn    = document.getElementById('clearSearch');
  const tabs        = document.querySelectorAll('.tab');
  const modal       = document.getElementById('gameModal');
  const backdrop    = document.getElementById('modalBackdrop');
  const modalTitle  = document.getElementById('modalTitle');
  const modalFavBtn = document.getElementById('modalFavBtn');
  const modalClose      = document.getElementById('modalClose');
  const modalFullscreen = document.getElementById('modalFullscreen');
  const fsIconExpand    = document.getElementById('fsIconExpand');
  const fsIconCollapse  = document.getElementById('fsIconCollapse');
  const gameFrame       = document.getElementById('gameFrame');

  let activeGameId = null;

  // ── Load games list ───────────────────────────────────────
  async function loadGames() {
    // Try games/index.json first
    try {
      const res = await fetch('games/index.json?_=' + Date.now());
      if (res.ok) {
        const data = await res.json();
        allGames = data.map((g, i) => ({
          id:   g.file.replace(/[^a-z0-9]/gi, '_'),
          name: g.name || fileToName(g.file),
          file: g.file,
        }));
        render();
        return;
      }
    } catch (_) {}

    // Fallback: show helpful empty state
    allGames = [];
    render();
  }

  // ── Helpers ───────────────────────────────────────────────
  function fileToName(file) {
    return file
      .replace(/\.html?$/i, '')
      .replace(/[-_]+/g, ' ')
      .replace(/\b\w/g, c => c.toUpperCase());
  }

  function saveFavorites() {
    localStorage.setItem('larpFavs', JSON.stringify([...favorites]));
  }

  function isFav(id) { return favorites.has(id); }

  function toggleFav(id) {
    if (favorites.has(id)) favorites.delete(id);
    else favorites.add(id);
    saveFavorites();
  }

  // ── Filtering & sorting ───────────────────────────────────
  function getVisible() {
    let list = allGames;

    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(g => g.name.toLowerCase().includes(q));
    }

    if (currentFilter === 'favorites') {
      list = list.filter(g => isFav(g.id));
    }

    // Favorites bubble to top
    list = [...list].sort((a, b) => {
      const af = isFav(a.id) ? 0 : 1;
      const bf = isFav(b.id) ? 0 : 1;
      return af - bf || a.name.localeCompare(b.name);
    });

    return list;
  }

  // ── Render ────────────────────────────────────────────────
  function render() {
    const visible = getVisible();
    grid.innerHTML = '';

    if (visible.length === 0) {
      emptyState.style.display = '';
      if (currentFilter === 'favorites' && !searchQuery) {
        emptyTitle.textContent = 'No favorites yet';
        emptyMsg.textContent = 'Star a game to pin it here.';
      } else if (searchQuery) {
        emptyTitle.textContent = 'No results';
        emptyMsg.innerHTML = `Nothing matched "<strong>${escHtml(searchQuery)}</strong>".`;
      } else if (allGames.length === 0) {
        emptyTitle.textContent = 'No games yet';
        emptyMsg.innerHTML = 'Add <code>.html</code> files to the <code>games/</code> folder, run <code>scan.py</code>, then refresh.';
      }
      return;
    }

    emptyState.style.display = 'none';

    visible.forEach((game, idx) => {
      const card = buildCard(game, idx);
      grid.appendChild(card);
    });
  }

  function buildCard(game, idx) {
    const fav = isFav(game.id);
    const card = document.createElement('div');
    card.className = 'game-card' + (fav ? ' favorited' : '');
    card.style.animationDelay = `${idx * 30}ms`;
    card.dataset.id = game.id;

    card.innerHTML = `
      <div class="card-thumb">
        <div class="card-thumb-pattern"></div>
        <svg class="card-thumb-icon" width="40" height="40" viewBox="0 0 40 40" fill="none">
          <rect x="6" y="6" width="28" height="28" rx="4" stroke="#c9a84c" stroke-width="1.5" fill="none"/>
          <path d="M14 20h12M20 14v12" stroke="#c9a84c" stroke-width="1.5" stroke-linecap="round"/>
        </svg>
        <span class="fav-badge">★ Fav</span>
      </div>
      <div class="card-body">
        <div class="card-name">${escHtml(game.name)}</div>
        <div class="card-footer">
          <span class="card-play">Play →</span>
          <button class="fav-btn ${fav ? 'active' : ''}" data-id="${game.id}" title="${fav ? 'Remove favorite' : 'Add to favorites'}">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="${fav ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2">
              <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/>
            </svg>
          </button>
        </div>
      </div>
    `;

    // Click card → open game
    card.addEventListener('click', (e) => {
      if (e.target.closest('.fav-btn')) return;
      openGame(game);
    });

    // Fav button
    card.querySelector('.fav-btn').addEventListener('click', (e) => {
      e.stopPropagation();
      toggleFav(game.id);
      render();
      if (activeGameId === game.id) syncModalFav();
    });

    return card;
  }

  function escHtml(str) {
    return str.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  // ── Modal / game launcher ─────────────────────────────────
  function openGame(game) {
    activeGameId = game.id;
    modalTitle.textContent = game.name;
    gameFrame.src = 'games/' + game.file;
    syncModalFav();
    modal.style.display = 'flex';
    document.body.style.overflow = 'hidden';
  }

  function closeGame() {
    modal.style.display = 'none';
    gameFrame.src = '';
    activeGameId = null;
    document.body.style.overflow = '';
  }

  function syncModalFav() {
    if (!activeGameId) return;
    const fav = isFav(activeGameId);
    modalFavBtn.classList.toggle('active', fav);
    modalFavBtn.querySelector('svg').setAttribute('fill', fav ? 'currentColor' : 'none');
    modalFavBtn.title = fav ? 'Remove favorite' : 'Add to favorites';
  }

  modalClose.addEventListener('click', closeGame);
  backdrop.addEventListener('click', closeGame);

  // ── Fullscreen ────────────────────────────────────────────
  function syncFsIcons() {
    const isFs = !!document.fullscreenElement;
    fsIconExpand.style.display   = isFs ? 'none'  : '';
    fsIconCollapse.style.display = isFs ? ''      : 'none';
    modalFullscreen.title = isFs ? 'Exit fullscreen' : 'Fullscreen';
  }

  modalFullscreen.addEventListener('click', () => {
    if (!document.fullscreenElement) {
      gameFrame.requestFullscreen().catch(() => {
        // Fallback: fullscreen the whole modal panel instead
        gameFrame.closest('.modal-panel').requestFullscreen().catch(() => {});
      });
    } else {
      document.exitFullscreen();
    }
  });

  document.addEventListener('fullscreenchange', syncFsIcons);

  modalFavBtn.addEventListener('click', () => {
    if (!activeGameId) return;
    toggleFav(activeGameId);
    syncModalFav();
    render();
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && modal.style.display !== 'none') closeGame();
  });

  // ── Search ────────────────────────────────────────────────
  searchInput.addEventListener('input', () => {
    searchQuery = searchInput.value.trim();
    clearBtn.classList.toggle('visible', searchQuery.length > 0);
    render();
  });

  clearBtn.addEventListener('click', () => {
    searchInput.value = '';
    searchQuery = '';
    clearBtn.classList.remove('visible');
    searchInput.focus();
    render();
  });

  // ── Tabs ──────────────────────────────────────────────────
  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      tabs.forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      currentFilter = tab.dataset.filter;
      render();
    });
  });

  // ── Init ──────────────────────────────────────────────────
  loadGames();
})();
